Object.values(groups).forEach(g=>{g.items.sort((a,b)=>(a.rank||9)-(b.rank||9));g.cat=Object.entries(g.cats).sort((a,b)=>b[1]-a[1])[0][0];g.sub=g.items[0].sub;g.uses=[...new Set(g.items.map(i=>i.use))];});
const G=Object.values(groups);
const gBySlug=Object.fromEntries(G.map(g=>[g.slug,g]));
const month=new Date(D.built).getMonth()+1;
const curSeason=month>=3&&month<=5?"봄":month<=8&&month>=6?"여름":month>=9&&month<=11?"가을":"겨울";

/* ---------- pages ---------- */
const P={};
P.home=()=>{
  const seasonRecs=D.recipes.filter(r=>r.seasons.includes(curSeason));
  return `<div class="home-hero"><div>
    <div class="latin">Aroma for everyday moments</div>
    <h1>하루의 장면마다,<br>어울리는 향 한 방울</h1>
    <p class="lead">잠들기 전, 일에 몰입할 때, 샤워를 마친 저녁처럼 생활 속 장면에서 고르는 레시피예요. 모든 레시피에는 희석 비율과 안전 태그가 함께 있어요.</p>
    <div class="chips" style="margin-top:16px"><a class="chip lav" href="#aroma-101">처음이라면, 아로마 101</a><a class="chip" href="#situations">상황별 레시피</a></div>
  </div>${photo("이른 아침 창가, 말린 라벤더와 유리 디퓨저, 리넨 위 부드러운 자연광, 넓은 여백","tall")}</div>
  <section class="s"><div class="eyebrow">Care</div><h2>${LEAF}몸 케어 · 마음 케어</h2><div class="catgrid">
    <a class="cat body" href="#body-care"><h3>몸 케어</h3><p class="note">바르고, 담그고, 감싸는 시간</p><ul>${G.filter(g=>g.cat==="몸 케어").map(g=>`<li>${esc(g.sub)}</li>`).join("")}</ul></a>
    <a class="cat mind" href="#mind-care"><h3>마음 케어</h3><p class="note">향으로 공간과 기분을 바꾸는 시간</p><ul>${G.filter(g=>g.cat==="마음 케어").map(g=>`<li>${esc(g.sub)}</li>`).join("")}</ul></a>
  </div></section>
  <section class="s"><div class="eyebrow">Find your scent</div><h2>${LEAF}세 가지 길로 찾아보기</h2>${explorePaths()}</section>
  <section class="s"><a class="cat mind" href="#my-scent" style="text-align:center"><div class="eyebrow">Find your scent type</div><h3>나에게 어울리는 향은?</h3><p class="note" style="margin-top:4px">질문 여섯 개 또는 MBTI로 찾아보는 향 취향 타입 →</p></a></section>
  <section class="s"><div class="eyebrow">Season</div><h2>${LEAF}지금, ${curSeason}의 레시피</h2>
    ${seasonRecs.length?`<div class="grid g3">${seasonRecs.slice(0,6).map(rcard).join("")}</div>`:pending(curSeason+" 레시피","시즌 칸에 '"+curSeason+"'이 들어간 레시피가 없어요")}
    <div class="chips" style="margin-top:12px">${Object.keys(SEASON).map(s=>`<a class="chip out" href="#season-${SEASON[s]}">${esc(s)}</a>`).join("")}</div></section>
  <section class="s"><div class="eyebrow">Moments</div><h2>${LEAF}상황별 레시피</h2><div class="grid g3">${G.map(t5card).join("")}</div></section>
  <section class="s"><div class="eyebrow">Oil dictionary</div><h2>${LEAF}오일 사전</h2><div class="grid g3">${D.oils.filter(o=>!o.missing).map(ocard).join("")}</div>
    <p style="margin-top:12px"><a href="#oils">오일 ${D.oils.length}종 모두 보기 →</a></p></section>`;
};
function t5card(g){const n=g.items.length;return `<a class="card" href="#situation-${g.slug}"><div class="note">${esc(g.cat)} · 레시피 ${n}개</div><h3>${esc(g.name)}</h3>
  <div class="note" style="margin-top:6px">${g.items.slice(0,3).map(i=>esc(i.name)).join(" · ")}</div></a>`;}
function explorePaths(){
  return `<div class="path">
   <div class="card"><h3>① 분위기별</h3><div class="chips">${Object.keys(MOOD).map(m=>`<a class="chip" href="#mood-${MOOD[m]}">${esc(m)}</a>`).join("")}</div></div>
   <div class="card"><h3>② 용도별</h3><div class="chips">${Object.keys(USE).map(u=>`<a class="chip lav" href="#use-${USE[u]}">${USEICO[u]} ${esc(u)}</a>`).join("")}</div></div>
   <div class="card"><h3>③ 향 계열별</h3><div class="chips">${Object.keys(SCENT).map(s=>`<a class="chip out" href="#scent-${SCENT[s]}">${esc(s)}</a>`).join("")}</div></div></div>`;
}
P.explore=()=>`<div class="narrow"><div class="crumb"><a href="#home">홈</a> › 분위기·용도·향</div><section class="s"><h1>어떻게 찾아볼까요?</h1><p class="lead">지금 기분, 쓰고 싶은 방법, 좋아하는 향 중 편한 길로 골라 보세요.</p></section></div>${explorePaths()}`;
function catPage(cat,key){
  const gs=G.filter(g=>g.cat===cat), rs=D.recipes.filter(r=>r.cat===cat);
  return `<div class="crumb"><a href="#home">홈</a> › ${cat}</div><section class="s"><h1>${cat}</h1><p class="lead">${cat==="몸 케어"?"바르고, 담그고, 감싸는 시간을 위한 레시피예요.":"향으로 공간과 기분을 바꾸는 시간을 위한 레시피예요."}</p></section>
  <section class="s"><h2>${LEAF}생활 상황으로 고르기</h2><div class="grid g3">${gs.map(t5card).join("")||pending("생활 상황","")}</div></section>
  <section class="s"><h2>${LEAF}${cat} 레시피 전체 (${rs.length})</h2><div class="grid g3">${rs.map(rcard).join("")}</div></section>`;
}
P["body-care"]=()=>catPage("몸 케어");
P["mind-care"]=()=>catPage("마음 케어");
P.situations=()=>`<div class="crumb"><a href="#home">홈</a> › 상황별 레시피</div><section class="s"><h1>상황별 레시피</h1><p class="lead">생활 속 장면마다 어울리는 레시피를 모았어요. 재료가 적은 입문용부터 보여 드려요.</p></section>
  ${["마음 케어","몸 케어"].map(c=>`<section class="s"><h2>${LEAF}${c}</h2><div class="grid g3">${G.filter(g=>g.cat===c).map(t5card).join("")}</div></section>`).join("")}`;
function situationPage(slug){
  const g=gBySlug[slug]; if(!g) return notFound();
  const tips=g.items.map(i=>i.tip).filter(Boolean).slice(0,3);
  const others=G.filter(x=>x!==g&&x.cat===g.cat).concat(G.filter(x=>x!==g&&x.cat!==g.cat)).slice(0,3);
  return `<div class="narrow"><div class="crumb"><a href="#home">홈</a> › <a href="#situations">상황별 레시피</a> › ${esc(g.sub)}</div>
  <section class="s"><div class="eyebrow">${esc(g.cat)}</div><h1>${esc(g.name)}</h1><p class="lead">레시피 ${g.items.length}개 · ${g.uses.map(esc).join(" · ")}</p>
  <div class="grid" style="margin-top:16px">${g.items.map(rcard).join("")}</div></section>
  <section class="s"><h2>${LEAF}효과를 높이는 팁</h2><div class="tips">${tips.length?`<ul>${tips.map(t=>`<li>${esc(t)}</li>`).join("")}</ul>`:pending("팁","")}</div></section>
  <section class="s"><h2>${LEAF}함께 보면 좋은 상황</h2><div class="grid">${others.map(t5card).join("")}</div></section></div>`;
}
function recipePage(id){
  const r=recById[id]; if(!r) return notFound();
  const skin=r.area&&r.area!=="해당 없음";
  const ingRows=r.ings.map(i=>{const o=oilById[i.oil];return `<tr><td>${o?`<a href="#oil-${o.id}">${esc(i.name)}</a>`:esc(i.name)}</td><td class="r">${esc(i.drops)}방울</td></tr>`}).join("");
  const related=D.recipes.filter(x=>x!==r&&x.moods.some(m=>r.moods.includes(m))).slice(0,3);
  const g=groups[r.top];
  return `<div class="narrow"><div class="crumb"><a href="#home">홈</a> › <a href="#${r.cat==="몸 케어"?"body-care":"mind-care"}">${esc(r.cat)}</a> › ${esc(r.sub)}</div>
  <div class="rhead"><div class="sub">${USEICO[r.use]||""} <a href="#use-${USE[r.use]}">${esc(r.use)}</a> · ${esc(r.level)}${status(r.status)}</div>
    <h1>${esc(r.name)}</h1>
    <div class="chips">${r.moods.map(m=>`<a class="chip" href="#mood-${MOOD[m]}">${esc(m)}</a>`).join("")}${r.scent?`<a class="chip out" href="#scent-${SCENT[r.scent]}">${esc(r.scent)}</a>`:""}</div>
    ${safety(r,true)}</div>
  ${r.ings.length?`<div class="rthumbs">${r.ings.map(i=>{const o=oilById[i.oil];return o?`<a href="#oil-${o.id}">${oilImg(o,"sm")}<span>${esc(o.ko)}</span></a>`:""}).join("")}</div>`:""}
  <section class="s"><h2>${LEAF}재료와 비율</h2>
    ${r.use==="티"?`<table class="ing"><tr><th>허브</th></tr><tr><td>${esc(r.herb)}</td></tr><tfoot><tr><td>${esc(r.base)} ${esc(r.ml)}ml · 에센셜 오일은 넣지 않아요</td></tr></tfoot></table>`:
    `<table class="ing"><thead><tr><th>에센셜 오일</th><th style="text-align:right">양</th></tr></thead><tbody>${ingRows}</tbody>
     <tfoot><tr><td>베이스: ${esc(r.base)}</td><td class="r">총 ${esc(r.ml)}ml</td></tr></tfoot></table>
     <div class="conc"><div class="kv"><div class="k">총 방울</div><div class="v">${esc(r.total)}방울</div></div>
     <div class="kv"><div class="k">희석 농도 ${skin?"("+esc(r.area)+")":""}</div><div class="v">${skin?pct(r.conc):"피부 적용 없음"}</div></div></div>
     ${skin?`<div class="small-note">1ml ≈ 20방울 기준 · ${r.area==="얼굴"?"얼굴은 1% 이하":"바디는 2~3% 이하"}를 지켜요</div>`:""}`}
  </section>
  <section class="s"><h2>${LEAF}만드는 법</h2>${steps(r.steps)}</section>
  ${r.use==="티"?"":recipeSubs(r)}
  <section class="s"><h2>${LEAF}기대 효과</h2><div class="effect"><p>${esc(r.effect)}</p><div style="margin-top:10px">${ev(r.ev)}</div></div>
    ${r.tip?`<div class="tips" style="margin-top:12px"><b style="font-size:13px;color:var(--lav-800)">효과를 높이는 팁</b><p style="margin-top:4px">${esc(r.tip)}</p></div>`:""}</section>
  <section class="s"><h2><svg class="leaf" viewBox="0 0 24 24" fill="none" stroke="#B4574F" stroke-width="1.4"><path d="M12 3 2 20h20L12 3Z"/><path d="M12 10v4M12 17v.5"/></svg>주의사항</h2>
    <div class="caution"><h3>꼭 지켜 주세요</h3>${bullets(r.caution)}</div></section>
  ${g?`<section class="s"><h2>${LEAF}같은 상황의 레시피</h2><div class="grid">${t5card(g)}</div></section>`:""}
  ${related.length?`<section class="s"><h2>${LEAF}비슷한 분위기의 레시피</h2><div class="grid">${related.map(rcard).join("")}</div></section>`:""}<div class="small-note" style="margin-top:28px">이 내용은 질병을 낫게 하거나 예방하려는 목적이 아니에요. <a href="#disclaimer">의료 면책 고지 보기</a></div></div>`;
}
function listPage(kind,slug){
  const conf={mood:[MOODi,"분위기별","moods",MOODDESC],use:[USEi,"용도별","use",USEDESC],scent:[SCENTi,"향 계열별","scent",SCENTDESC],season:[SEASONi,"시즌","seasons",{}]}[kind];
  const name=conf[0][slug]; if(!name) return notFound();
  const rs=D.recipes.filter(r=>Array.isArray(r[conf[2]])?r[conf[2]].includes(name):r[conf[2]]===name);
  const os=kind==="mood"?D.oils.filter(o=>o.moods.includes(name)):kind==="scent"?D.oils.filter(o=>o.scent===name):[];
  const allKeys=Object.keys(inv(conf[0]));
  return `<div class="crumb"><a href="#home">홈</a> › <a href="#explore">${conf[1]}</a> › ${esc(name)}</div>
  <section class="s"><h1>${esc(name)}</h1><p class="lead">${esc(conf[3][name]||"")}</p>
  <div class="filters">${allKeys.map(k=>`<button class="${k===name?"on":""}" onclick="go('${kind}-${conf[0]===MOODi?MOOD[k]:conf[0]===USEi?USE[k]:conf[0]===SCENTi?SCENT[k]:SEASON[k]}')">${esc(k)}</button>`).join("")}</div></section>
  ${kind==="use"?`<section class="s"><h2>${LEAF}${esc(name)} 가이드</h2>${pending(name+" 사용 가이드 본문","도구 준비, 기본 비율, 자주 하는 실수를 담을 자리예요")}</section>`:""}
  <section class="s"><h2>${LEAF}레시피 (${rs.length})</h2>${rs.length?`<div class="grid g3">${rs.map(rcard).join("")}</div>`:pending(name+" 레시피","레시피DB에서 이 값으로 태그된 레시피가 아직 없어요")}</section>
  ${os.length?`<section class="s"><h2>${LEAF}어울리는 오일</h2><div class="grid g3">${os.map(ocard).join("")}</div></section>`:""}`;
}
